void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 st = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    // Background color
    vec3 color = vec3(0.0);
    vec3 gear_color = vec3(0.4);

    // Radius and angle
    float r = length(st) * 2.0f;
    float a = atan(st.x, st.y);

    float AA = 6./iResolution.y;

    // Gear rotation
    a -= iTime;

    // Gear pattern
    float f = abs(cos(2.5 * a)) * 0.5 + 0.5;
    f = smoothstep(-0.5, 1.0, cos(a * 11.0)) * 0.2 + 0.8;

    // Inner hole radius
    float inner_hole = 0.3; // Adjust this value for the size of the hole

    // Mix color for the gear, excluding the inner circle (hole)

        color = mix(color, gear_color, smoothstep(inner_hole, inner_hole+AA, r)*1.0 - smoothstep(f, f + AA, r));


    fragColor = vec4(color, 1.0);
}
